import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"セキュリティと秘密情報","description":"","frontmatter":{},"headers":[],"relativePath":"operations/security.md","filePath":"operations/security.md","lastUpdated":1793464466000}`),a={name:`operations/security.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="セキュリティと秘密情報" tabindex="-1">セキュリティと秘密情報 <a class="header-anchor" href="#セキュリティと秘密情報" aria-label="Permalink to “セキュリティと秘密情報”">​</a></h1><h2 id="キーを区別する" tabindex="-1">キーを区別する <a class="header-anchor" href="#キーを区別する" aria-label="Permalink to “キーを区別する”">​</a></h2><table tabindex="0"><thead><tr><th>名前</th><th>用途</th><th>保存先</th></tr></thead><tbody><tr><td>CLOUDFLARE_API_TOKEN</td><td>配備・D1・Access等の操作</td><td>作業環境/CIの秘密管理</td></tr><tr><td>JEV_API_KEY</td><td>Jevの実判定</td><td>Worker/Node.jsの実行時Secret</td></tr><tr><td>ADMIN_TOKEN</td><td>本番の最初のSuperuser登録</td><td>実行時Secret。初回後の通常ログインには使わない</td></tr><tr><td>AUTH_SECRET</td><td>診断認可の署名</td><td>環境ごとの独立した実行時Secret</td></tr></tbody></table><p><strong>ビルド用のCloudflareトークンと、アプリ実行時のJevキーは別です。</strong> 値をGit、HTML、JavaScript、通常変数、Issuesへ入れないでください。管理画面にも値を出しません。</p><p>Cloudflareの設定では、APIキーを通常のテキスト変数ではなく<strong>Secret</strong>として登録します。APIから設定全体を表示すると、平文変数が出力に混ざることがあります。確認は名前・種類等に限定します。</p><h2 id="パスキーと管理セッション" tabindex="-1">パスキーと管理セッション <a class="header-anchor" href="#パスキーと管理セッション" aria-label="Permalink to “パスキーと管理セッション”">​</a></h2><p>管理CookieはSecure・HttpOnly・SameSite=Laxで、ブラウザのWeb StorageやURLへ置きません。サーバーはランダムなセッション値のハッシュを保持します。</p><p>書き込みではOriginとCSRFを検証し、サイトの権限もサーバーで確認します。ユーザー停止や権限変更は、画面を隠すだけでなくAPIへ反映します。</p><h2 id="previewの保護" tabindex="-1">Previewの保護 <a class="header-anchor" href="#previewの保護" aria-label="Permalink to “Previewの保護”">​</a></h2><p>Preview URLは既定では公開です。Cloudflare Accessで担当者を限定し、Worker側でもAccess JWTを検証します。D1、Secret、費用カウンターを本番と分離します。</p><p>Accessを設定するAPIトークンの権限は、ログインユーザーのJevSense権限を自動で与えるものではありません。</p><h2 id="独自コード" tabindex="-1">独自コード <a class="header-anchor" href="#独自コード" aria-label="Permalink to “独自コード”">​</a></h2><p>サイトと同じ権限で実行されます。コード登録者を管理者に限定し、レビューと確認を行ってください。variablesもブラウザに見える情報です。</p><h2 id="外部送信とログ" tabindex="-1">外部送信とログ <a class="header-anchor" href="#外部送信とログ" aria-label="Permalink to “外部送信とログ”">​</a></h2><p>対象ページのメタデータ・URLパス・追加連携を確認し、同意とプライバシー表示を整えます。Jevの保持条件・料金等は提供元へ確認してください。</p><p>プロキシやAPMへ要求本文、Cookie、Authorization、診断認可、閲覧履歴を記録しないようにします。CORSのOriginは通常HTTPクライアントから偽装できるため、費用攻撃の認証対策として扱いません。</p><h2 id="費用と可用性" tabindex="-1">費用と可用性 <a class="header-anchor" href="#費用と可用性" aria-label="Permalink to “費用と可用性”">​</a></h2><p>日次上限と同時実行数を設定します。失敗した実モデル要求も日次上限に算入し、自動再試行しません。アプリ内の上限だけで請求額の厳密な上限を保証するものではありません。</p><p>WorkersのIP制限はロケーション単位の近似的な制限です。Node.jsのカウンターはプロセス内で、再起動するとリセットします。</p><h2 id="漏洩が疑われるとき" tabindex="-1">漏洩が疑われるとき <a class="header-anchor" href="#漏洩が疑われるとき" aria-label="Permalink to “漏洩が疑われるとき”">​</a></h2><p>該当の提供元でキーを再発行・失効し、使っている環境のSecretを更新します。認証に関する問題では、ユーザー停止やセッション終了も併用します。</p><p>AUTH_SECRETの変更は診断認可を無効にしますが、DB参照型の管理セッションをそれだけですべて終了するわけではありません。必要に応じて明示的にセッションを失効してください。</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};